const D = { density: .6, scale: 1, energy: .6, speed: 1, connect: .6, twinkle: .6, hue: 220, x: .5, y: .5, style: 'night-sky', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
const TAU = 6.283185307;
const NMAX = 1000;

// ---- build starfield + constellation chains on seed change ----
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  S.stars = [];
  for (let i = 0; i < NMAX; i++) {
    const rr = Math.sqrt(fr(i * 3 + 11)) * 1.18;   // uniform disk, slightly beyond frame
    const aa = fr(i * 3 + 12) * TAU;
    const b = 0.22 + fr(i * 3 + 13) * 0.78;         // base brightness
    const tw = fr(i * 3 + 14) * TAU;                // twinkle phase
    const twr = 0.5 + fr(i * 3 + 15) * 1.9;         // twinkle rate
    const big = fr(i * 3 + 16);                     // size roll (few big anchors)
    const tint = fr(i * 3 + 17);                    // color variation
    S.stars.push({ rr, aa, b, tw, twr, big, tint, cx: Math.cos(aa) * rr, cy: Math.sin(aa) * rr });
  }
  // constellation groups: greedy nearest-neighbour chains among inner bright stars
  S.groups = [];
  const GN = 15;
  for (let g = 0; g < GN; g++) {
    const start = Math.floor(fr(g * 7 + 101) * 300);
    const chain = [start];
    let cur = start;
    const L = 3 + Math.floor(fr(g * 7 + 102) * 4);
    for (let k = 0; k < L; k++) {
      let best = -1, bd = 1e9;
      const cs = S.stars[cur];
      for (let j = 0; j < 340; j++) {
        if (chain.indexOf(j) >= 0) continue;
        const s2 = S.stars[j];
        const dx = s2.cx - cs.cx, dy = s2.cy - cs.cy, d = dx * dx + dy * dy;
        if (d < bd && d > 0.0005) { bd = d; best = j; }
      }
      if (best < 0 || bd > 0.09) break;
      chain.push(best); cur = best;
    }
    if (chain.length >= 3) S.groups.push({ chain, ph: fr(g * 7 + 103) * TAU, rate: 0.6 + fr(g * 7 + 104) * 1.1 });
  }
}

// ---- style palette config ----
const h0 = P.hue;
let baseC, cloudHues, lineA, lineB, schematic = false, mono = false, starFn;
if (P.style === 'zodiac-gold') {
  baseC = [258, 55, 10];
  cloudHues = [[42, 70, 30], [30, 75, 22], [278, 45, 18]];
  lineA = [45, 85, 96]; lineB = [30, 92, 90];
  starFn = t => t < 0.6 ? [46, 30 + t * 40, 0] : (t < 0.85 ? [38, 60, 0] : [30, 15, 0]);
} else if (P.style === 'aurora-sky') {
  baseC = [202, 68, 10];
  cloudHues = [[158, 70, 30], [176, 65, 26], [120, 60, 22], [268, 45, 16]];
  lineA = [165, 80, 96]; lineB = [110, 78, 92];
  starFn = t => t < 0.6 ? [190, 18 + t * 25, 0] : (t < 0.85 ? [160, 40, 0] : [0, 0, 0]);
} else if (P.style === 'blueprint') {
  baseC = [214, 82, 26];
  cloudHues = [[214, 70, 32], [210, 60, 30]];
  lineA = [208, 12, 100]; lineB = [208, 28, 92];
  schematic = true;
  starFn = t => [208, 10, 0];
} else if (P.style === 'mono') {
  baseC = [220, 8, 6];
  cloudHues = [[0, 0, 16], [220, 6, 14]];
  lineA = [0, 0, 82]; lineB = [0, 0, 58];
  mono = true;
  starFn = t => [0, 0, 0];
} else { // night-sky (default)
  baseC = [222, 70, 11];
  cloudHues = [[(h0 - 18 + 360) % 360, 60, 30], [(h0 + 20) % 360, 55, 26], [192, 70, 30], [276, 50, 22]];
  lineA = [188, 80, 96]; lineB = [45, 82, 95];
  starFn = t => t < 0.55 ? [210, 22 + t * 30, 0] : (t < 0.85 ? [45, 45, 0] : [0, 0, 0]);
}

// ---- nebula backdrop buffer (rebuild on size/style/seed/hue) ----
const BW = 240, BH = Math.max(90, Math.round(BW * height / width));
const nkey = BW + 'x' + BH + '|' + P.style + '|' + (P.seed | 0) + '|' + Math.round(P.hue / 8);
if (!S.neb || S.neb.width !== BW || S.neb.height !== BH) { S.neb = createGraphics(BW, BH); S.neb.pixelDensity(1); S.nkey = null; }
if (S.nkey !== nkey) {
  S.nkey = nkey;
  const g = S.neb;
  g.colorMode(HSB, 360, 100, 100, 100);
  g.noStroke();
  g.background(baseC[0], baseC[1], baseC[2]);
  if (schematic) {
    // technical grid + faint wash
    g.push(); g.blendMode(BLEND); g.stroke(208, 30, 44, 40); g.strokeWeight(1);
    const step = BW / 16;
    for (let gx = 0; gx <= BW; gx += step) g.line(gx, 0, gx, BH);
    for (let gy = 0; gy <= BH; gy += step) g.line(0, gy, BW, gy);
    g.pop();
  } else {
    g.blendMode(ADD);
    const NC = 30;
    for (let c = 0; c < NC; c++) {
      const ch = cloudHues[c % cloudHues.length];
      const px = fr(c * 5 + 301) * BW, py = fr(c * 5 + 302) * BH;
      const rad = BW * (0.14 + fr(c * 5 + 303) * 0.42);
      const al = 3 + fr(c * 5 + 304) * 7;
      const layers = 5;
      for (let q = 0; q < layers; q++) {
        const rr = rad * (1 - q / layers);
        g.fill(ch[0], ch[1], ch[2], al);
        g.ellipse(px, py, rr * 2, rr * 2);
      }
    }
    g.blendMode(BLEND);
  }
  g.colorMode(RGB, 255);
}

// ---- per-frame dynamics ----
const halfD = 0.5 * Math.hypot(width, height);
const cx = P.x * width, cy = P.y * height;
const rot = K.t * (0.010 + 0.020 * P.speed);
const cosr = Math.cos(rot), sinr = Math.sin(rot);
const af = P.alpha / 100;
const expo = 0.65 + P.energy * 0.55 + A.bass * 0.7 + K.intensity * 0.2;
const twk = 0.35 + P.twinkle * 0.6;
const nStars = Math.min(NMAX, Math.floor(200 + P.density * 800));
const baseSz = (0.7 + P.scale * 1.5);
const trebleSpark = A.treble * 3;

// backdrop
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(S.neb, 0, 0, width, height);
pop();

// constellation lines (under stars)
push();
blendMode(ADD);
noFill();
for (let gi = 0; gi < S.groups.length; gi++) {
  const grp = S.groups[gi];
  const env = Math.pow(0.5 + 0.5 * Math.sin(K.t * (0.11 + 0.07 * P.speed) * grp.rate + grp.ph + K.section * 0.6), 2.3);
  const la = env * (0.3 + P.connect * 0.95) * (0.55 + P.energy * 0.6) * (0.8 + A.mid * 0.6) * af;
  if (la < 0.02) continue;
  const col = (gi % 2) ? lineB : lineA;
  stroke(col[0], col[1], col[2], Math.min(85, la * 78));
  strokeWeight(schematic ? 1.0 : 0.8 + la * 1.7);
  beginShape();
  for (let ci = 0; ci < grp.chain.length; ci++) {
    const s = S.stars[grp.chain[ci]];
    const px = cx + halfD * (s.cx * cosr - s.cy * sinr);
    const py = cy + halfD * (s.cx * sinr + s.cy * cosr);
    vertex(px, py);
  }
  endShape();
}
blendMode(BLEND);
pop();

// stars
push();
blendMode(ADD);
noStroke();
for (let i = 0; i < nStars; i++) {
  const s = S.stars[i];
  const px = cx + halfD * (s.cx * cosr - s.cy * sinr);
  const py = cy + halfD * (s.cx * sinr + s.cy * cosr);
  if (px < -30 || px > width + 30 || py < -30 || py > height + 30) continue;
  const tw = (1 - twk) + twk * (0.5 + 0.5 * Math.sin(K.t * s.twr * (0.7 + P.speed * 0.4) + s.tw + trebleSpark));
  const bght = Math.min(1, s.b * tw * expo);
  const sz = baseSz * (0.55 + s.big * 1.9) * (0.65 + bght * 0.7);
  const c = starFn(s.tint);
  const sat = mono ? 0 : (schematic ? 8 : c[1]);
  const hue = c[0];
  fill(hue, sat, 55 + 45 * bght, (28 + 62 * bght) * af);
  if (schematic) {
    // schematic star ticks (plus mark)
    const r = sz * 1.6;
    rectMode(CENTER);
    rect(px, py, r, 0.9); rect(px, py, 0.9, r);
    rectMode(CORNER);
  } else {
    ellipse(px, py, sz, sz);
    if (s.big > 0.86 && bght > 0.45) {
      fill(hue, sat * 0.6, 100, 11 * bght * af);
      ellipse(px, py, sz * 4.2, sz * 4.2);
    }
  }
}
blendMode(BLEND);
pop();

// shooting star (continuous, periodic, small-area)
const per = Math.max(2.2, 6.0 - Math.min(3.4, P.speed * 1.3));
const cyc = Math.floor(K.t / per);
const frc = (K.t - cyc * per) / per;
if (frc < 0.15 && P.energy > 0.05) {
  const life = frc / 0.15;
  const ang = fr(cyc * 13 + 201) * TAU;
  const dx = Math.cos(ang), dy = Math.sin(ang);
  const sx = (fr(cyc * 13 + 202)) * width;
  const sy = (fr(cyc * 13 + 203)) * height * 0.7;
  const travel = halfD * 1.3;
  const hx = sx + dx * life * travel, hy = sy + dy * life * travel;
  const fade = Math.sin(life * Math.PI);
  push();
  blendMode(ADD);
  const tailN = 14;
  for (let s = 0; s < tailN; s++) {
    const f = s / tailN;
    const tx = hx - dx * f * 70 * (0.6 + P.scale * 0.5);
    const ty = hy - dy * f * 70 * (0.6 + P.scale * 0.5);
    noStroke();
    const hc = mono ? [0, 0] : (schematic ? [208, 12] : [190, 30]);
    fill(hc[0], hc[1], 100, (1 - f) * 55 * fade * af);
    circle(tx, ty, (1 - f) * (2.4 + P.scale * 1.6) + 0.8);
  }
  fill(0, 0, 100, 80 * fade * af);
  circle(hx, hy, 2.5 + P.scale * 1.4);
  blendMode(BLEND);
  pop();
}
